using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using QuanLyKho.DTOs;using QuanLyKho.Services;namespace QuanLyKho.Controllers;[ApiController][Route("api/categories")][Authorize(Roles="Admin,Manager")]public sealed class CategoriesController:ControllerBase{readonly CategoryService s;public CategoriesController(CategoryService s)=>this.s=s;[HttpGet]public async Task<IActionResult> GetAll()=>Ok(await s.GetAllAsync());[HttpGet("{id:int}")]public async Task<IActionResult> Get(int id)=>Ok(await s.GetByIdAsync(id));[HttpPost]public async Task<IActionResult> Create(CategoryRequest r){var x=await s.CreateAsync(r);return CreatedAtAction(nameof(Get),new{id=x.Id},x);}[HttpPut("{id:int}")]public async Task<IActionResult> Update(int id,CategoryRequest r)=>Ok(await s.UpdateAsync(id,r));[HttpDelete("{id:int}")]public async Task<IActionResult> Delete(int id){await s.DeleteAsync(id);return NoContent();}}